/**
 * PWA — service worker registration, active ONLY on the GitHub Pages host
 * so local dev / preview never fights a stale cache. The worker itself is
 * generated by build.mjs with the package version baked into the cache name.
 */
import { env } from './env';

export function registerServiceWorker(): void {
  if (!env.isPages) return;
  if (!('serviceWorker' in navigator)) return;
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('./sw.js').catch(() => {
      /* offline support is a bonus, never a blocker */
    });
  });
}
